import { useState, useRef, useEffect } from 'react';

export default function CustomerSearch({ users = [], selectedUserId, onSelect }) {
  const [query, setQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const wrapperRef = useRef(null);

  // Debugging: Check if users are actually reaching this component
  useEffect(() => {
    console.log("CustomerSearch received users:", users);
  }, [users]);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event) {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target)) setIsOpen(false);
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Filter with optional chaining (?.) to prevent crashes if a field is missing
  const filteredUsers = users.filter(user => 
    user?.fullName?.toLowerCase().includes(query.toLowerCase()) || 
    user?.email?.toLowerCase().includes(query.toLowerCase())
  );

  const selectedUser = users.find(u => u._id === selectedUserId);

  return (
    <div ref={wrapperRef} className="relative w-full">
      <input
        type="text"
        placeholder="Search by name or email..."
        value={isOpen ? query : (selectedUser ? `${selectedUser.fullName} (${selectedUser.email})` : query)}
        onChange={(e) => {
          setQuery(e.target.value);
          setIsOpen(true);
          onSelect(''); 
        }}
        onFocus={() => setIsOpen(true)}
        className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-indigo-500"
      />
      
      {isOpen && (
        <ul className="absolute z-10 w-full mt-1 max-h-60 overflow-y-auto bg-white border border-gray-200 rounded-lg shadow-xl">
          {filteredUsers.length > 0 ? (
            filteredUsers.map((user) => (
              <li
                key={user._id}
                onClick={() => {
                  onSelect(user._id);
                  setQuery('');
                  setIsOpen(false);
                }}
                className="px-4 py-3 cursor-pointer hover:bg-indigo-50 border-b border-gray-50 last:border-0"
              >
                <div className="font-semibold text-gray-900 text-sm">{user.fullName}</div>
                <div className="text-xs text-gray-500">{user.email}</div>
              </li>
            ))
          ) : (
            <li className="px-4 py-3 text-sm text-gray-500 text-center">
              {users.length === 0 ? "No students exist for this company yet." : "No matching names found."}
            </li>
          )}
        </ul>
      )}
    </div>
  );
}
